tafsir_text:
وقوله :  {  يَعْرِفُونَهُ كَما يَعْرِفُونَ أَبْناهُمُ .  .  .  }

ذُكر أنّ عمر بن الخطاب قال لعبد الله بن سَلاَم :  ما هذه المعرفة التي تعرفون بها محمد صلى الله عليه وسلم ؟  قال :  والله لأَنابِهِ إذا رأيته أعرفُ مِنى بابني وهو يلعب مع الصبيان ؛  لأني لا أشكُّ فيه أنه محمد صلى الله عليه وسلم ؛  ولست أدرى ما صنع النساء في الابن .  فهذه المعرفة لصفته في كتابهم .

وجاء التفسير في قوله :  {  خَسِرُواْ أَنْفُسَهُمْ } يقال :  ليس من مؤمن ولا كافر إلا له منزل في الجنة وأهل وأزواج ،  فمن أسلم وسعد صار إلى منزله وأزواجه ( ومن كفر صار منزله وأزواجه ) إلى من أسلم وسعد .  فذلك قوله {  الذِين يَرِثُون الفِردوسَ } يقول :  يرثون منازل الكفار ،  وهو قوله :  {  الذِين خسِروا أنفسهم وأهليهم } .

وقوله :  {  قُلْ مَن يُنَجِّيكُمْ مِّن ظُلُماتِ الْبَرِّ وَالْبَحْرِ تَدْعُونَهُ تَضَرُّعاً وَخُفْيَةً }

يقال :  خُفيَة وخِفية .  وفيها لغة بالواو ،  - ولا تصلح في القراءة - :  خُفوة وخِفوة ؛  كما قيل :  قد حَلّ حُبْوته وحِبوته وحِبْيته .

وقوله :  {  لَّئِنْ أَنجَانا مِنْ هَذِهِ }

قراءة أهل الكوفة ،  - وكذلك هي في مصاحفهم -  " أن جِ ى ن ألف "  وبعضهم بالألف ( أنجانا ) وقراءة الناس ( أنجيتنا ) بالتاء .

وقوله :  {  وَذَرِ الَّذِينَ اتَّخَذُواْ دِينَهُمْ لَعِباً وَلَهْواً .  .  .  }

يقال :  ليس من قوم إلاَّ ولهم عيد فهم يَلهُون في أَعيادهم ،  إلا أُمَّة محمد صلى الله عليه وسلم ؛  فإن أعيادهم بِرّ وصلاة وتكبير وخير .

وقوله :  {  وَذَكِّرْ بِهِ أَن تُبْسَلَ نَفْسٌ } أي ترتهن ( والعرب تقول :  هذا عليك بَسْل أي حرام .  ولذلك قيل :  أسَد باسل أي لا يُقْرَب ) والعرب تقول :  أعْطِ الراقِي بُسْلته ،  وهو أجر الرقية .

وقوله :  {  فَلَما جَنَّ عَلَيْهِ الْلَّيْلُ .  .  .  }

يقال :  جنّ عليه الليل ،  وأَجَنَّ ،  وأَجنَّه الليل وجَنّه الليل ؛  وبالألف أجود إذا ألقيت ( على ) وهي أكثر من جنَّه الليل .

يقال في قوله :  {  فَلَما جَنَّ عَلَيْهِ الْلَّيْلُ رَأي كَوْكَباً قَالَ هذَا رَبِّي } قولان :  إنما قال :  هذا ربّى استدراجا للحجَّة على قومه ليعيب آلهتهم أَنها ليست بشيء ،  وأن الكوكب والقمر والشمس أكبر منها ولسن بآلهة ؛  ويقال :  إنه قاله على الوجه الآخر ؛  كما قال الله تبارك وتعالى لمحمد صلى الله عليه وسلم :  {  أَلَمْ يَجِدْكَ يَتِيما فَآوَى .  وَوَجَدَكَ ضَالاّ فَهَدَى } واحتجوا ها هنا بقول إبراهيم :  {  لَئِنْ لَمْ يَهْدِني رَبِّى لأَكُونَنّ مِنَ الْقَوْمِ الضَّالِّينَ } .

وقوله :  {  وَلِتُنذِرَ أُمَّ الْقُرَى .  .  .  }

يقال في التفسير :  إنّ أمّ القرى مَكَّة .

وقوله :  {  وَالَّذِينَ يُؤْمِنُونَ بِالآخِرَةِ يُؤْمِنُونَ بِهِ } الهاء تكون لمحمد صلى الله عليه وسلم وللتنزيل .

وقوله :  {  وَلَقَدْ جِئْتُمُونا فُرَادَى .  .  .  }

وهو جمع .  والعرب تقول :  [ قوم ] فرادى وفرادُ يا هذا فلا يجُرونها ،  شبهت بثُلاَث ورُبَاع .  وفرادى واحدها فَرْد ،  وفرِد ،  وفريد ،  وفراد للجمع ،  ولا يجوز فرد في هذا المعنى .  وأنشدني بعضهم :

ترى النُعَراتِ الزُرْق تحت لَبَانه *** فُرَادَ ومثنى أصعقتها صواهِله

وقوله :  {  لَقَد تَّقَطَّعَ بَيْنَكُمْ .  .  .  }

قرأ حمزة ومجاهد ( بينُكُمْ ) يريد وصلكم .  وفي قراءة عبد الله ( لقد تقطع ما بينَكم ) وهو وجه الكلام .  إذا جعل الفعل لبين ترك نصبا ؛  كما قالوا :  أتانى دونك من الرجال فترك نصبا وهو في موضع رفع ؛  لأنه صفة .  وإذا قالوا :  هذا دون من الرجال رفعوه في موضع الرفع .  وكذلك تقول :  بين الرجلين بين بعيد ،  وبون بعيد ؛  إذا أفردته أجريته في العربية وأعطيته الإعراب .

وقوله :  {  وجعلوا لله شركاء الجن }

إن شئت جعلت {  الجن } تفسير للشركاء .  وإن شئت جعلت نصبه على :  جعلوا الجن شركاء لله تبارك وتعالى .

وقوله :  {  وخرقوا } :  واخترقوا وخلقوا واختلقوا ،  يريد :  افتروا .

وقوله :  {  وكذلك نصرف الآيات وليقولوا درست }

يقولون :  تعلمت من يهود .  وفي قراءة عبد الله {  وليقولوا درس } يعنون محمدا صلى الله عليه وسلم .  وهو كما تقول في الكلام :  قالوا لي :  أساء ،  وقالوا لي :  أسأت .  ومثله :  {  قل للذين كفروا سيغلبون } و {  ستغلبون } .

وقرأ بعضهم ( دارست ) يريد :  جادلت اليهود وجادلوك .  وكذلك قال ابن عباس .  وقرأها مجاهد ( دارست ) وفسرها :  قرأت على اليهود وقرءوا عليك .  وقد قرئت ( درست ) أي قرئت وتليت .  وقرءوا ( درست ) وقرءوا ( درست ) يريد تقادمت ،  أي هذا الذي يتلوه علينا شيء قد تطاول ومر بنا .

وقوله :  {  أَوَ مَن كَانَ مَيْتاً فَأَحْيَيْناهُ }

أي كان ضالاّ فهديناه .

وقوله :  {  نُوراً يَمْشِي بِهِ فِي الناسِ } يعنى إيمانه .

وقوله :  {  الَّذِينَ أَجْرَمُواْ صَغَارٌ عِندَ اللَّهِ }

أي من عند الله ،  كذلك قال المفسرون .  وهو في العربية ؛  كما تقول :  سيأتيني رزق عندك ،  كقولك :  سيأتيني الذي عند الله .  سيصيبهم الصغار الذي عنده ،  ولمحمد صلى الله عليه وسلم أن ينزله بهم .  ولا يجوز في العربية أن تقول :  جئت عند زيد ،  وأنت تريد :  من عند زيد .

وقد يكون قوله :  {  صَغَارٌ عِندَ اللَّهِ } أنهم اختاروا الكفر تعَزُّزا وأنَفَة من اتباع محمد صلى الله عليه وسلم ،  فجعل الله ذلك صَغَارا عنده .

وقوله :  {  يَا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُمْ }

يقول :  قد أضللتم كثيرا .

وقوله :  {  وَقَالَ أَوْلِيَاؤُهُم مِّنَ الإِنْسِ رَبَّنا اسْتَمْتَعَ بَعْضُنا بِبَعْضٍ } فالاستمتاع من الإنس بالجنّ أن الرجل كان إذا فارق فاستوحش أو قتل صيدا من صيدهم فخاف قال :  أعوذ بسيّد هذا الوادي ،  فيبيت آمنا في نفسه .  وأما استمتاع الجنّ بالإنس فما نالوا بهم من تعظيم الإنس إيّاهم ،  فكان الجِنّ يقولون :  سُدْنا الجنّ والإنس .

وقوله :  {  فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ }

( مَنْ تَكُونُ لَهُ ) في موضع رفع ،  ولو نصبتها كان صوابا ؛  كما قال الله تبارك وتعالى :  {  وَاللّهُ يَعْلَمُ المُفْسِدَ مِنَ الْمُصْلِحِ } .

وقوله :  {  مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ } إذا كان الفعل في مذهب مصدر مؤنثا مثل العاقبة ،  والموعظة ،  والعافية ،  فإنك إذا قدّمت فعله قبله أنَّثته وذكّرته ؛  كما قال الله عزّ وجلّ :  {  فَمَنْ جَاءهُ مَوْعِظَةٌ مِنْ رَبِّهِ } بالتذكير ،  وقال :  {  قَدْ جَاءتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ } بالتأنيث .  وكذلك {  وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ } {  وَأَخَذَتِ } فلا تهابنّ من هذا تذكيرا ولا تأنيثا .

وقوله :  {  وَأَنَّ هذا صِرَاطِي مُسْتَقِيما }

تكسر إنَّ إذا نويت الاستئناف ،  وتفتحها من وقوع ( أتل ) عليها .  وإن شئت جعلتها خفصا ،  تريد {  ذلكمْ وَصَّاكُمْ بِهِ } و {  وَأَنَّ هذا صِرَاطِي مُسْتَقِيما فَاتَّبِعُوهُ } .

وقوله :  {  وَلاَ تَتَّبِعُواْ السُّبُلَ } يعنى اليهودية والنصرانية .  يقول :  لا تتبعوها فتضلوا .

وقوله :  {  ثُمَّ آتَيْنا مُوسَى الْكِتَابَ تَماما على الَّذِي أَحْسَنَ }

تماما على المحسن .  ويكون المحسن في مذهب جمع ؛  كما قال :  {  إِنَّ الإِنْسَانَ لَفي خُسْرٍ } .  وفي قراءة عبد الله ( تَماما على الذِين أحسنوا ) تصديقا لذلك .  وإن شئت جعلت ( الذي ) على معنى ( ما ) تريد :  تماما على ما أحسن موسى ،  فيكون المعنى :  تماما على إحسانه .  ويكون ( أحسن ) مرفوعا ؛  تريد على الذي هو أحسن ،  وتنصب ( أحسن ) ها هنا تنوى بها الخفض ؛  لأن العرب تقول :  مررت بالذي هو خير منك ،  وشر منك ،  ولا يقولون :  مررت بالذي قائم ؛  لأن ( خيرا منك ) كالمعرفة ؛  إذ لم تدخل فيه الألف واللام .  وكذلك يقولون :  مررت بالذي أخيك ،  وبالذي مثلِك ،  إذا جعلوا صلة الذي معرفة أو نكرة لا تدخلها الألف واللام جعلوها تابعة للذي ؛  أنشدني الكسائي :

إن الزُّبيرىَّ الذي مِثْلَ الحَلَمْ *** مَشَّى بأسلابك في أهل العَلَم

وقوله :  {  إِنَّ الَّذِينَ فَرَّقُواْ دِينَهُمْ .  .  .  }

قرأها على ( فارقوا ) ،  وقال :  والله ما فرَّقوه ولكن فارقوه .  وهم اليهود والنصارى .  وقرأها الناس ( فَرَّقُوا دِينَهُمْ ) وكلّ وجه .

وقوله :  {  لَّسْتَ مِنْهُمْ فِي شَيْءٍ } يقول من قتالهم في شيء ،  ثم نسختها :  {  فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ } .

وقوله :  {  فَلَهُ عَشْرُ أَمْثَالِها }

من خفض يريد :  فله عشر حسناتٍ أمثالها .  ولو قال هاهنا :  فله عشر مِثْلِها ؛  يريد عشر حسنات مثلها كان صوابا .  ومن قال :  عشْرٌ أَمثالها جعلهنّ من نعت العشر .  و( مثل ) يجوز توحيده :  أن تقول في مثله من الكلام :  هم مثلكم ،  وأمثالكم ؛  قال الله تبارك وتعالى :  {  إِنكم إِذاً مثلهم } فوحَّد ،  وقال :  {  ثم لا يكونوا أَمثالكم } فجمع .  ولو قلت :  عَشْرٌ أمثالها كما تقول :  عندي خمسةٌ أثوابٌ لجاز .

وقوله :  {  مَن جَاء بِالْحَسَنَةِ } :  بلا إله إلا الله ،  والسيئة :  الشِّرك .
